from soar.integrations.catalog_edr import edr_capability_matrix
from soar.playbooks.frontier import evaluate_expression
from soar.playbooks.template import lookup, render

responses = data.get("responses", {})

if kind in ("start", "end", "set_var", "transform", "delay", "task",
            "incident_update", "notification"):
    return ({"branch": "next" if kind != "end" else "__end__"}, None)

if kind == "condition":
    for clause in node.get("when", []):
        if evaluate_expression(clause.get("if", ""), context):
            return ({"branch": "then", "matched": clause.get("if")}, None)
    return ({"branch": "else"}, None)

if kind == "switch":
    subject = render(node.get("subject", ""), context, "text")
    known = subject in node.get("cases", {})
    return ({"branch": "case" if known else "default", "subject": subject}, None)

if kind == "for_each":
    items = lookup(str(node.get("items", "")).strip("{} "), context) or []
    limit = int(node.get("max_iterations", 100))
    return ({"count": min(len(items), limit), "total": len(items),
             "branch": "body"}, None)

if kind == "while":
    return ({"iterations": 0, "branch": "next"}, None)

if kind == "parallel":
    return ({"branches": len(node.get("branches", [])),
             "branch": "branches"}, None)

if kind == "approval":
    decision = data.get("approvals", {}).get(
        node.get("action_key"), data.get("approvals", {}).get("default", "approve"))
    branch = {"approve": "on_approve", "reject": "on_reject",
              "timeout": "on_timeout"}.get(decision, "on_approve")
    return ({"branch": branch, "simulated_decision": decision}, None)

if kind == "ai":
    action = node.get("action", "analyze")
    reply = data.get("ai", {}).get(action)
    if reply is None:
        return (None, "the fixture has no AI response for %r" % action)
    output = dict(reply)
    output["branch"] = "next"
    return (output, None)

if kind == "response":
    action = node.get("action")
    agents = (data.get("host") or {}).get("agent_ids", {})
    matrix = edr_capability_matrix()
    capable = [cid for cid, cap in matrix.items()
               if cap["agent_key"] in agents and action in cap["supported"]]
    if not capable:
        # The blind spot the fixture is there to find: an action no EDR on
        # this host can perform takes the on_unsupported branch, and if the
        # playbook has not wired one it fails here rather than in production.
        if node.get("on_unsupported"):
            return ({"branch": "on_unsupported", "reason": "no capable EDR"}, None)
        return (None,
                "no EDR on %s supports %s and on_unsupported is not wired"
                % ((data.get("host") or {}).get("hostname"), action))
    command = matrix[capable[0]]["supported"][action]["command"]
    reply = responses.get(command)
    if reply is None:
        return (None, "the fixture has no response for %r" % command)
    output = dict(reply)
    output["branch"] = "next"
    output["resolved_command"] = command
    return (output, None)

if kind in ("command", "http", "script", "sub_playbook"):
    key = node.get("command") or node.get("playbook") or kind
    reply = responses.get(key)
    if reply is None:
        return (None, "the fixture has no response for %r" % key)
    output = dict(reply) if isinstance(reply, dict) else {"result": reply}
    output["branch"] = "next"
    return (output, None)

return ({"branch": "next"}, None)

from soar.playbooks.template import lookup

visited = {entry["node"].split("/")[-1] for entry in trace}
kinds = {entry["kind"] for entry in trace}
failures = []
checked = 0

for assertion in assertions or []:
    checked += 1
    kind = assertion.get("kind")

    if kind == "reached":
        if assertion.get("node") and assertion["node"] not in visited:
            failures.append("expected to reach %s" % assertion["node"])
        if assertion.get("node_kind") and assertion["node_kind"] not in kinds:
            failures.append("expected to reach a %s node"
                            % assertion["node_kind"])

    elif kind == "not_reached":
        if assertion.get("node") in visited:
            failures.append("did not expect to reach %s" % assertion["node"])

    elif kind == "branch":
        taken = [e["branch"] for e in trace
                 if e["node"].split("/")[-1] == assertion.get("node")]
        if assertion.get("expect") not in taken:
            failures.append("%s took %s, expected %s"
                            % (assertion.get("node"), taken or "nothing",
                               assertion.get("expect")))

    elif kind == "variable":
        actual = lookup(assertion.get("path", ""), context)
        if actual != assertion.get("equals"):
            failures.append("%s was %r, expected %r"
                            % (assertion.get("path"), actual,
                               assertion.get("equals")))

    elif kind == "no_unhandled_error":
        broken = [e for e in trace if e.get("status") == "failed"]
        if broken:
            failures.append("unhandled failure at %s" % broken[0]["node"])

    else:
        failures.append("unknown assertion kind %r" % kind)

return {"checked": checked, "failures": failures}
